"""Offline, dependency-free evidence and controlled RDF comparison dashboard."""
from __future__ import annotations
import html, json
from pathlib import Path
from .stage_v08 import ROOT, RESULTS, read_csv, sha256


def build():
    data={
      'claims':read_csv(RESULTS/'P2_CHEM_EVIDENCE_100_v08.csv'),
      'sources':read_csv(RESULTS/'P2_SOURCE_TYPE_AUDIT_20.csv'),
      'questions':read_csv(RESULTS/'P3_V05_CQ_DEVELOPMENT_8.csv'),
      'queries':read_csv(RESULTS/'P3_V06_RDF_QUERY_DIAGNOSTICS_24.csv'),
      'p2':json.loads((RESULTS/'P2_V08_REVIEW_SUMMARY.json').read_text()),
      'p3':json.loads((RESULTS/'P3_V06_AUDIT_SUMMARY.json').read_text()),
    }
    payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('&','\\u0026')
    template=r'''<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>ThaiHerb Evidence Audit v0.8 / RDF v0.6</title><style>
:root{color-scheme:light;font-family:Inter,system-ui,-apple-system,'Segoe UI',Arial,sans-serif;--bg:#f5f7fa;--card:#fff;--ink:#172a3b;--muted:#607184;--line:#dce4ec;--accent:#145e87;--accentbg:#e7f2f7;--warn:#9b5c08;--border:1px solid var(--line)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);line-height:1.5}.wrap{max-width:1380px;margin:auto;padding:26px 25px 75px}
header{background:linear-gradient(120deg,#17344e,#236d83);color:#fff;padding:34px 0}header .wrap{padding:0 25px}h1{margin:7px 0;font-size:clamp(1.6rem,3vw,2.45rem);letter-spacing:-.035em}h2{font-size:1.3rem;margin:0 0 15px}h3{font-size:1.05rem;margin:0 0 10px}.muted{color:var(--muted)}header .muted{color:#cbdbe3}
.kicker{font-size:.75rem;font-weight:750;letter-spacing:.13em;text-transform:uppercase}.lead{max-width:850px;margin:0;font-size:1rem}.tabbar{display:flex;gap:7px;flex-wrap:wrap;margin:21px 0}.tabbar button,.filters select,.filters input{border:var(--border);background:#fff;color:var(--ink);padding:10px 13px;border-radius:8px;font-size:.91rem}.tabbar button{cursor:pointer}.tabbar button[aria-selected="true"]{background:var(--accent);color:#fff;border-color:var(--accent)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #a2c6e0;outline-offset:2px}
.panel{display:none}.panel.active{display:block}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.metric,.section,.notice{background:var(--card);border:var(--border);border-radius:13px;padding:22px}.metric b{display:block;font-size:2rem;line-height:1.1;margin:7px 0}.metric small{color:var(--muted)}.section{margin:16px 0}.notice{background:#fff9ee;border-color:#eddfbe;margin:15px 0}.filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:15px}.filters input{min-width:280px;flex:2}.filters select{flex:1;min-width:190px}table{width:100%;border-collapse:collapse;font-size:.86rem}th{text-align:left;background:#eaf1f6;color:#34576b;font-weight:700}th,td{padding:10px 11px;border-bottom:1px solid var(--line);vertical-align:top}tbody tr:hover{background:#f5fafd}.scroll{overflow-x:auto;max-height:650px;overflow-y:auto}.count{font-variant-numeric:tabular-nums}.pill{font-size:.75rem;border:1px solid #d4e0e9;background:#f0f5f9;border-radius:20px;padding:4px 8px;display:inline-block;white-space:nowrap}.pill.review{border-color:#e5d6b6;background:#fbf2db}.pill.full{background:#e4f1eb;border-color:#bad8c8}.pill.unknown{background:#f0f1f4;border-color:#dfe2e8}.barrow{display:grid;grid-template-columns:minmax(230px,1fr) 2fr 60px;gap:16px;align-items:center;margin:14px 0}.bar{height:11px;border-radius:9px;background:#e9eef2;overflow:hidden}.fill{background:var(--accent);height:100%;border-radius:9px}.source-link{color:var(--accent);word-break:break-word;text-decoration:none}.source-link:hover{text-decoration:underline}.detail{background:#f5f9fb;border:1px solid #dbe8ef;padding:17px;border-radius:10px;margin-top:10px;white-space:pre-wrap;font-size:.87rem}.model-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.model{border:var(--border);border-radius:10px;padding:16px;background:#fff}.model h3{border-bottom:var(--border);padding-bottom:10px}.mono{font-family:ui-monospace,Consolas,monospace;font-size:.81rem;word-break:break-word}.small{font-size:.83rem}footer{color:#667a89;margin-top:25px;font-size:.8rem}
@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}.model-grid{grid-template-columns:1fr}.barrow{grid-template-columns:1fr 1.5fr 45px}.wrap{padding:16px 12px}header .wrap{padding:0 14px}}
@media(max-width:480px){.grid{grid-template-columns:1fr 1fr}.metric{padding:15px}.metric b{font-size:1.55rem}.filters input{min-width:100%}}
</style></head><body>
<header><div class="wrap"><div class="kicker">Thai Herbal Knowledge Graph / Controlled Research Release</div><h1>Evidence Integrity & RDF Query Explorer</h1><p class="lead muted">Paper 2 v0.8 / Paper 3 v0.6 • Frozen V3 input; evidence-level separation; no expert gold or comparative accuracy claims.</p></div></header>
<main class="wrap"><div class="tabbar" role="tablist" aria-label="Explorer sections">
<button class="tab" aria-selected="true" data-id="overview">Overview</button><button class="tab" aria-selected="false" data-id="claims">100 Chemical Claims</button><button class="tab" aria-selected="false" data-id="sources">20 Source Studies</button><button class="tab" aria-selected="false" data-id="rdf">M1 / M2 / M3 Queries</button><button class="tab" aria-selected="false" data-id="gates">Research Gates</button></div>
<section class="panel active" id="overview"><div class="grid"><div class="metric"><small>P2 chemical claims</small><b>100</b><small>83 distinct internal compound IDs</small></div><div class="metric"><small>Primary full-text matched</small><b id="nfull">5</b><small>Limited to named-analyte source table</small></div><div class="metric"><small>Still not claim-verified</small><b id="nunknown">66</b><small>No specific compound evidence adjudicated</small></div><div class="metric"><small>P3 frozen assertions</small><b>208</b><small>71 formula, 100 chemistry, 30 targets, 7 clinical</small></div></div>
<div class="section"><h2>Evidence levels — exact claim counts</h2><div id="bars"></div><p class="small muted">An abstract name match is not a full-text claim confirmation; a review is not primary compound measurement. The hydrolysis-only group represents a chemically processed fraction, not compounds proven to be present unchanged in native medicinal material.</p></div>
<div class="notice"><b>Scientific integrity note.</b> SHACL Core has not been executed in this local environment; custom structural regression checks cannot substitute for pySHACL conformance. Expert gold is absent, and M3 superiority over M1/M2 is NOT established.</div></section>
<section class="panel" id="claims"><div class="section"><h2>Herb–compound evidence assertions</h2><div class="filters"><input id="claimsearch" type="search" placeholder="Search herb, compound, source or ID" aria-label="Search chemistry claims"/><select id="level" aria-label="Filter evidence status"><option value="">All evidence levels</option></select><select id="herb" aria-label="Filter herb"><option value="">All 20 herbs</option></select></div><div class="small muted" id="claimcount"></div><div class="scroll"><table><thead><tr><th>Assertion</th><th>Herb</th><th>Compound</th><th>Source type</th><th>Claim evidence</th><th>Source</th></tr></thead><tbody id="claimrows"></tbody></table></div><div id="claimdetail" class="detail" aria-live="polite">Select a source link or search to review the individual claim and locator.</div></div></section>
<section class="panel" id="sources"><div class="section"><h2>Publication type and material context</h2><p class="muted">A publication-type match is a source audit only. It is not a compound-by-compound confirmation.</p><div class="filters"><input id="sourcesearch" type="search" placeholder="Search source, herb, material or study type" aria-label="Search sources"/></div><div class="scroll"><table><thead><tr><th>Source</th><th>Species</th><th>Publication type</th><th>Material/interpretation warning</th><th>Publication</th></tr></thead><tbody id="sourcerows"></tbody></table></div></div></section>
<section class="panel" id="rdf"><div class="section"><h2>Identical-input RDF projection diagnostics</h2><div class="grid"><div class="metric"><small>M1 distinct triples</small><b>207</b></div><div class="metric"><small>M2 triples</small><b>1,501</b></div><div class="metric"><small>M3 triples</small><b>2,733</b></div><div class="metric"><small>Development query runs</small><b>24</b><small>8 cases × 3 models</small></div></div></div>
<div class="section"><h2>Compare one development question</h2><div class="filters"><select id="question" aria-label="Select competency question"></select></div><p id="questiontext"></p><div class="model-grid" id="modelcards"></div><p class="muted small">All responses originate from the same 208 archived assertions. M1's collapsed SPO relation for CLIN005/CLIN006 is a structural difference; no accuracy labels are available.</p></div></section>
<section class="panel" id="gates"><div class="section"><h2>Research acceptance gates</h2><table><thead><tr><th>Gate</th><th>State</th><th>Requirement before publication</th></tr></thead><tbody>
<tr><td>Frozen V3 identity</td><td>PASS</td><td>208 unique assertions, source version kept intact</td></tr>
<tr><td>Claim-level chemical evidence</td><td>PARTIAL</td><td>66 claims still unverified; 9 review abstract name matches, 10 prior secondary review claims; source contexts differ</td></tr>
<tr><td>Original 35 chemical class map</td><td>BLOCKED</td><td>Original class mapping not recovered; candidate mapping may not be called exact replication</td></tr>
<tr><td>Source-disjoint external benchmark</td><td>BLOCKED</td><td>No eligible independently verified held-out corpus</td></tr>
<tr><td>RDF projection integrity</td><td>PASS</td><td>Computational representation only; does not validate scientific truth</td></tr>
<tr><td>45 vs 67 source registry</td><td>PARTIAL</td><td>45 source IDs present; historical 67-entry registry not reconciled</td></tr>
<tr><td>Clinical canonical objects</td><td>BLOCKED</td><td>Seven source-text objects preserved; IDs not invented</td></tr>
<tr><td>pySHACL Core</td><td>NOT RUN</td><td>Requires real pySHACL run + negative controls in networked environment</td></tr>
<tr><td>Blinded M1/M2/M3 benchmark</td><td>BLOCKED</td><td>Two independent expert reviews and case adjudication required</td></tr></tbody></table></div></section>
<footer>Data snapshot: 2026-11-07. Offline static file. This explorer reports provenance and research development only; do not use for treatment or product authorization.</footer></main>
<script id="data" type="application/json">__JSON_PAYLOAD__</script><script>
(()=>{'use strict';const data=JSON.parse(document.getElementById('data').textContent);const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));const url=s=>/^https:\/\//.test(String(s||''))?s:'';
const panels=document.querySelectorAll('.panel');document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.setAttribute('aria-selected',String(x===b)));panels.forEach(x=>x.classList.toggle('active',x.id===b.dataset.id))}));
const counts=data.p2.claim_evidence_counts;document.getElementById('nfull').textContent=counts.PRIMARY_FULLTEXT_MATCH||0;document.getElementById('nunknown').textContent=counts.NOT_VERIFIED||0;
const nice={PRIMARY_FULLTEXT_MATCH:'Primary analytical full-text table',PRIMARY_ABSTRACT_ONLY:'Primary study abstract',PRIMARY_ABSTRACT_AFTER_HYDROLYSIS:'Primary after chemical hydrolysis',SECONDARY_ABSTRACT_NAME_MATCH:'Review abstract name match',SECONDARY_ONLY:'Secondary literature only',NOT_VERIFIED:'No specific claim verification'};
const sorted=Object.entries(counts).sort((a,b)=>b[1]-a[1]);document.getElementById('bars').innerHTML=sorted.map(([k,n])=>`<div class="barrow"><div>${esc(nice[k]||k)}</div><div class="bar"><div class="fill" style="width:${Number(n)}%"></div></div><b class="count">${n}</b></div>`).join('');
const level=document.getElementById('level');for(const k of Object.keys(counts)){const op=document.createElement('option');op.value=k;op.textContent=nice[k]||k;level.appendChild(op)}const herb=document.getElementById('herb');[...new Map(data.claims.map(x=>[x.herb_id,x.herb_id+' — '+x.herb_scientific_name])).entries()].sort().forEach(([key,text])=>{const x=document.createElement('option');x.value=key;x.textContent=text;herb.appendChild(x)});
const showClaims=()=>{const q=document.getElementById('claimsearch').value.toLowerCase();let items=data.claims.filter(x=>(!level.value||level.value===x.v08_claim_evidence_level)&&(!herb.value||herb.value===x.herb_id)&&Object.values(x).some(v=>String(v).toLowerCase().includes(q)));document.getElementById('claimcount').textContent=items.length+' / '+data.claims.length+' claims';document.getElementById('claimrows').innerHTML=items.map(x=>`<tr><td class="mono">${esc(x.assertion_id)}</td><td>${esc(x.herb_scientific_name)}</td><td><b>${esc(x.compound_label)}</b></td><td class="small">${esc(x.v08_source_type)}</td><td><span class="pill ${x.v08_claim_evidence_level==='NOT_VERIFIED'?'unknown':x.v08_claim_evidence_level==='PRIMARY_FULLTEXT_MATCH'?'full':'review'}">${esc(x.v08_claim_evidence_level)}</span></td><td><button class="source-link" style="border:0;background:none;cursor:pointer" data-claim="${esc(x.assertion_id)}">${esc(x.source_id)}</button></td></tr>`).join('');document.querySelectorAll('[data-claim]').forEach(b=>b.addEventListener('click',()=>{const x=data.claims.find(y=>y.assertion_id===b.dataset.claim);if(!x)return;let src=url(x.v08_source_access_url);document.getElementById('claimdetail').innerHTML='<b>'+esc(x.assertion_id)+' — '+esc(x.compound_label)+'</b>\nSpecies: '+esc(x.herb_scientific_name)+'\nEvidence: '+esc(x.v08_claim_evidence_level)+'\nSource type: '+esc(x.v08_source_type)+'\nLocator: '+esc(x.v08_claim_exact_locator)+'\nMaterial warning: '+esc(x.v08_material_scope_warning)+'\nReview: '+esc(x.v08_claim_review_reason)+(src?'\n<a class="source-link" href="'+esc(src)+'" target="_blank" rel="noopener noreferrer">Open publication</a>':'')}))};['claimsearch','level','herb'].forEach(id=>document.getElementById(id).addEventListener(id==='claimsearch'?'input':'change',showClaims));showClaims();
const showSources=()=>{const q=document.getElementById('sourcesearch').value.toLowerCase();document.getElementById('sourcerows').innerHTML=data.sources.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(q))).map(x=>`<tr><td class="mono">${esc(x.source_id)}</td><td>${esc(x.scientific_name)}</td><td>${esc(x.publication_type_source_screen)}</td><td>${esc(x.source_scope_and_material_warning)}</td><td>${url(x.source_verified_url)?`<a class="source-link" href="${esc(x.source_verified_url)}" target="_blank" rel="noopener noreferrer">Open source</a>`:'No link'}</td></tr>`).join('')};document.getElementById('sourcesearch').addEventListener('input',showSources);showSources();
const qSelect=document.getElementById('question');data.questions.forEach(c=>{let op=document.createElement('option');op.value=c.case_id;op.textContent=c.case_id+' — '+c.category;qSelect.appendChild(op)});const showQuestion=()=>{let c=data.questions.find(x=>x.case_id===qSelect.value);if(!c)return;document.getElementById('questiontext').textContent=c.question;document.getElementById('modelcards').innerHTML=['M1','M2','M3'].map(m=>{let r=data.queries.find(x=>x.case_id===c.case_id&&x.model===m);return `<div class="model"><h3>${m}</h3><div><b>Status:</b> ${esc(r.status)}</div><div><b>Relations:</b> ${esc(r.edge_count)}</div><div><b>Distinct assertion IDs:</b> ${esc(r.distinct_assertion_ids)}</div><div><b>Sources:</b> ${esc(r.citation_count)}</div><div class="mono"><b>Assertion IDs:</b> ${esc(r.assertion_ids||'Not in this projection')}</div><p class="small muted">${esc(r.qualification||'No additional qualification')}</p><div class="small"><b>Accuracy:</b> NOT EVALUATED</div></div>`}).join('')};qSelect.addEventListener('change',showQuestion);if(data.questions.length){qSelect.value=data.questions[0].case_id;showQuestion()}
})();
</script></body></html>'''
    text=template.replace('__JSON_PAYLOAD__',payload)
    out=ROOT/'dashboard'/'ThaiHerb_EvidenceIntegrity_v08_RDFv06.html'
    out.write_text(text,encoding='utf-8')
    return out

if __name__=='__main__':
    p=build();print(str(p),p.stat().st_size)